from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover the grid."""
    # Identical tiles are interchangeable, so keep a count for each normalized size.
    shape_counts = {}
    for a, b in tiles[:n]:
        shape = (min(a, b), max(a, b))
        shape_counts[shape] = shape_counts.get(shape, 0) + 1
    shapes = tuple(sorted(shape_counts))
    initial_counts = tuple(shape_counts[s] for s in shapes)
    areas = tuple(a * b for a, b in shapes)

    if h <= 0 or w <= 0:
        return False
    target = h * w
    if sum(c * area for c, area in zip(initial_counts, areas)) < target:
        return False

    @lru_cache(None)
    def can_make_area(counts, amount):
        if amount == 0:
            return True
        if amount < 0:
            return False
        for i, count in enumerate(counts):
            area = areas[i]
            if count and area <= amount:
                nxt = list(counts)
                nxt[i] -= 1
                if can_make_area(tuple(nxt), amount - area):
                    return True
        return False

    @lru_cache(None)
    def search(rows, counts, remaining):
        if remaining == 0:
            return True
        if remaining < 0 or not can_make_area(counts, remaining):
            return False

        # The first uncovered cell must be the top-left cell of the next tile:
        # all earlier cells in row-major order are already occupied.
        row = 0
        while row < h and rows[row] == (1 << w) - 1:
            row += 1
        if row == h:
            return False
        col = 0
        while rows[row] & (1 << col):
            col += 1

        options = []
        for i, ((a, b), count) in enumerate(zip(shapes, counts)):
            if not count:
                continue
            orientations = {(a, b), (b, a)}
            for th, tw in orientations:
                if row + th > h or col + tw > w:
                    continue
                bits = ((1 << tw) - 1) << col
                if any(rows[rr] & bits for rr in range(row, row + th)):
                    continue
                options.append((-(th * tw), i, th, tw, bits))

        # Larger placements tend to reduce the branching factor early.
        options.sort()
        for _, i, th, tw, bits in options:
            new_rows = list(rows)
            for rr in range(row, row + th):
                new_rows[rr] |= bits
            new_counts = list(counts)
            new_counts[i] -= 1
            if search(tuple(new_rows), tuple(new_counts), remaining - th * tw):
                return True
        return False

    return search((0,) * h, initial_counts, target)

