def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the periodic wallpaper pattern."""
    # For a unit square in a 1-by-2 strip, the diagonal cuts it in half
    # when it crosses its interior; otherwise the square is entirely one
    # color. The pattern repeats every 2 horizontally and 4 vertically.
    def doubled_below(t: int) -> int:
        if t <= 0:
            return 0
        if t == 1:
            return 1
        return 2

    cells = [[0] * 4 for _ in range(2)]
    for i in range(2):
        threshold = 2 if i == 0 else 1
        for y in range(4):
            j, r = divmod(y, 2)
            under = doubled_below(threshold - r)
            cells[i][y] = under if (i + j) % 2 == 0 else 2 - under

    prefix = [[0] * 5 for _ in range(3)]
    for i in range(2):
        for y in range(4):
            prefix[i + 1][y + 1] = (
                cells[i][y] + prefix[i][y + 1]
                + prefix[i + 1][y] - prefix[i][y]
            )
    period_total = prefix[2][4]

    def primitive(x: int, y: int) -> int:
        qx, rx = divmod(x, 2)
        qy, ry = divmod(y, 4)
        return (
            qx * qy * period_total
            + qx * prefix[2][ry]
            + qy * prefix[rx][4]
            + prefix[rx][ry]
        )

    return primitive(C, D) - primitive(A, D) - primitive(C, B) + primitive(A, B)

from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Find the minimum cost to monitor each section with the available sensors."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    states = {(0, 0): 0}
    for length in sections[:n]:
        a = (length + l1 - 1) // l1
        b = (length + l2 - 1) // l2
        options = []
        if a <= k1:
            options.append((a, 0, a * c1))
        if b <= k2:
            options.append((0, b, b * c2))
        if not options:
            return -1
        next_states = {}
        for (used_a, used_b), cost in states.items():
            for add_a, add_b, extra in options:
                total_a, total_b = used_a + add_a, used_b + add_b
                if total_a <= k1 and total_b <= k2:
                    key = (total_a, total_b)
                    next_states[key] = min(next_states.get(key, float("inf")), cost + extra)
        if not next_states:
            return -1
        states = next_states
    return min(states.values()) if states else -1

