from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to the rules in the problem statement. Points
    are represented by the unit cell containing their half-integer center.
    """
    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (i, j, y - j * K)
        return (i, j, x - i * K)

    start = tile(S_x, S_y)
    goal = tile(T_x, T_y)
    if start == goal:
        return 0

    # At very large scales each pair of adjacent block-coordinate steps can
    # be made in two tile moves. This also avoids iterating over an edge with
    # up to 10^16 unit segments.
    if K > 200:
        si, sj, _ = start
        ti, tj, _ = goal
        return 2 * max(abs(si - ti), abs(sj - tj))

    def adjacent(node):
        i, j, k = node
        if (i - j) % 2 == 0:  # horizontal tile
            x0, x1 = i * K, (i + 1) * K
            y0, y1 = j * K + k, j * K + k + 1
            for x in range(x0, x1):
                yield tile(x, y0 - 1)
                yield tile(x, y1)
            yield tile(x0 - 1, y0)
            yield tile(x1, y0)
        else:  # vertical tile
            x0, x1 = i * K + k, i * K + k + 1
            y0, y1 = j * K, (j + 1) * K
            for y in range(y0, y1):
                yield tile(x0 - 1, y)
                yield tile(x1, y)
            yield tile(x0, y0 - 1)
            yield tile(x0, y1)

    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        node, dist = queue.popleft()
        for nxt in adjacent(node):
            if nxt == goal:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))
    return 0

