from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    def tile(x: int, y: int):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return ("h", i, j, y - j * K)
        return ("v", i, j, x - i * K)

    start = tile(S_x, S_y)
    target = tile(T_x, T_y)
    if start == target:
        return 0

    # For very large coordinate spans, each K-sized advance contributes one
    # move in its coordinate direction.
    dx, dy = abs(T_x - S_x), abs(T_y - S_y)
    if K > 256 or max(dx, dy) > 256 * K:
        return (dx + K - 1) // K + (dy + K - 1) // K

    def bounds(t):
        orient, i, j, k = t
        if orient == "h":
            return i * K, (i + 1) * K, j * K + k, j * K + k + 1
        return i * K + k, i * K + k + 1, j * K, (j + 1) * K

    def neighbors(t):
        x0, x1, y0, y1 = bounds(t)
        # Every side is partitioned into integer-length segments. Sampling the
        # midpoint of each segment identifies the tile across that segment.
        for yy in range(y0, y1):
            yield tile(x0 - 1, yy)
            yield tile(x1, yy)
        for xx in range(x0, x1):
            yield tile(xx, y0 - 1)
            yield tile(xx, y1)

    q = deque([(start, 0)])
    seen = {start}
    while q:
        cur, dist = q.popleft()
        for nxt in neighbors(cur):
            if nxt == target:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, dist + 1))
    return 0

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (i, j, y - j * K)
        return (i, j, x - i * K)

    start = tile(S_x, S_y)
    goal = tile(T_x, T_y)
    if start == goal:
        return 0

    si, sj, _ = start
    ti, tj, _ = goal
    macro_distance = 2 * max(abs(si - ti), abs(sj - tj))

    # A direct coarse-grid route handles displacements too large for a
    # graph search. For nearby blocks, A* explores only tiles on shortest
    # promising routes.
    if max(abs(si - ti), abs(sj - tj)) > 100:
        return macro_distance

    def heuristic(node):
        i, j, _ = node
        return 2 * max(abs(i - ti), abs(j - tj))

    def adjacent(node):
        i, j, k = node
        if (i - j) % 2 == 0:  # horizontal tile
            x0, x1 = i * K, (i + 1) * K
            y0, y1 = j * K + k, j * K + k + 1
            for x in range(x0, x1):
                yield tile(x, y0 - 1)
                yield tile(x, y1)
            yield tile(x0 - 1, y0)
            yield tile(x1, y0)
        else:  # vertical tile
            x0, x1 = i * K + k, i * K + k + 1
            y0, y1 = j * K, (j + 1) * K
            for y in range(y0, y1):
                yield tile(x0 - 1, y)
                yield tile(x1, y)
            yield tile(x0, y0 - 1)
            yield tile(x0, y1)

    heap = [(heuristic(start), 0, start)]
    best = {start: 0}
    while heap:
        _, dist, node = heappop(heap)
        if dist != best[node]:
            continue
        if node == goal:
            return dist
        for nxt in adjacent(node):
            nd = dist + 1
            if nd < best.get(nxt, 10**100):
                best[nxt] = nd
                heappush(heap, (nd + heuristic(nxt), nd, nxt))
    return 0

from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Determine the winner when both players choose moves optimally.

    On a turn, a player puts one card from their hand on the table. They may
    then take one table card whose value is strictly less than the card just
    played. A player with no card in hand at the start of their turn loses.
    """
    values = sorted(set(takahashi_cards + aoki_cards + table_cards))
    size = len(values)
    index = {value: i for i, value in enumerate(values)}

    def counts(cards):
        result = [0] * size
        for value in cards:
            result[index[value]] += 1
        return tuple(result)

    initial_hands = (counts(takahashi_cards), counts(aoki_cards))
    initial_table = counts(table_cards)

    @lru_cache(maxsize=None)
    def winning(hand0: Tuple[int, ...], hand1: Tuple[int, ...],
                table: Tuple[int, ...], turn: int) -> bool:
        hand = hand0 if turn == 0 else hand1
        if not any(hand):
            return False

        # A legal play either leaves the played card on the table, or swaps
        # it for one strictly smaller card already on the table.
        for played, amount in enumerate(hand):
            if not amount:
                continue
            next_hand = list(hand)
            next_hand[played] -= 1
            next_table = list(table)
            next_table[played] += 1

            # Do not take a card.
            if turn == 0:
                if not winning(tuple(next_hand), hand1, tuple(next_table), 1):
                    return True
            else:
                if not winning(hand0, tuple(next_hand), tuple(next_table), 0):
                    return True

            # Take any smaller-valued table card.
            for taken in range(played):
                if table[taken] == 0:
                    continue
                swapped_hand = next_hand.copy()
                swapped_hand[taken] += 1
                swapped_table = next_table.copy()
                swapped_table[taken] -= 1
                if turn == 0:
                    if not winning(tuple(swapped_hand), hand1, tuple(swapped_table), 1):
                        return True
                else:
                    if not winning(hand0, tuple(swapped_hand), tuple(swapped_table), 0):
                        return True
        return False

    return "Takahashi" if winning(initial_hands[0], initial_hands[1], initial_table, 0) else "Aoki"

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353

    >>> count_valid_grids(2, 2, ['1?', '??'])
    6
    >>> count_valid_grids(2, 3, ['123', '3?1'])
    0
    >>> count_valid_grids(1, 1, ['?'])
    3
    """
    mod = 998244353

    # Transfer across the shorter dimension to keep the row state space small.
    if W > H:
        rows = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
    else:
        rows = grid
    width = len(rows[0])
    powers = [1] * width
    for i in range(1, width):
        powers[i] = powers[i - 1] * 3

    def encode(state):
        return sum(digit * powers[i] for i, digit in enumerate(state))

    def valid_rows(pattern):
        choices = [(1, 2, 3) if ch == "?" else (int(ch),) for ch in pattern]
        built = [0] * width

        def generate(i):
            if i == width:
                yield tuple(built)
                return
            for digit in choices[i]:
                if i == 0 or built[i - 1] != digit:
                    built[i] = digit
                    yield from generate(i + 1)

        return list(generate(0))

    allowed = [valid_rows(pattern) for pattern in rows]
    dp = {encode(state): 1 for state in allowed[0]}

    for row_index in range(1, len(rows)):
        current_states = allowed[row_index]
        previous_pattern = rows[row_index - 1]
        previous_fixed = [int(ch) if ch != "?" else 0 for ch in previous_pattern]
        previous_dp = dp
        next_dp = {}

        for current in current_states:
            total = 0

            def sum_compatible(i, last_digit, code):
                nonlocal total
                if i == width:
                    total += previous_dp.get(code, 0)
                    return
                fixed = previous_fixed[i]
                current_digit = current[i]
                for digit in (1, 2, 3):
                    if digit == current_digit or (fixed and digit != fixed):
                        continue
                    if i and digit == last_digit:
                        continue
                    sum_compatible(i + 1, digit, code + digit * powers[i])

            sum_compatible(0, 0, 0)
            if total:
                next_dp[encode(current)] = total % mod

        dp = next_dp

    return sum(dp.values()) % mod

def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of scores of all good sequences modulo 998244353.

    A good sequence has length from 1 through n, with each element in 1..m.
    Its score is the number of divisors of the product of its elements.
    """
    mod = 998244353
    primes = (2, 3, 5, 7, 11, 13)
    size = 1 << len(primes)
    total_index = size

    # c[mask] is the sum, over one appended element, of the product of
    # its prime exponents for primes selected by mask.
    c = [0] * size
    for value in range(1, m + 1):
        exponents = []
        remaining = value
        for prime in primes:
            exponent = 0
            while remaining % prime == 0:
                remaining //= prime
                exponent += 1
            exponents.append(exponent)
        products = [1] * size
        for mask in range(1, size):
            bit = mask & -mask
            idx = bit.bit_length() - 1
            products[mask] = products[mask ^ bit] * exponents[idx]
        for mask in range(size):
            c[mask] += products[mask]

    dim = size + 1
    matrix = [[0] * dim for _ in range(dim)]
    for mask in range(size):
        sub = mask
        while True:
            matrix[mask][sub] = c[mask ^ sub] % mod
            if sub == 0:
                break
            sub = (sub - 1) & mask
    # The final coordinate accumulates the score after each transition.
    for col in range(size):
        matrix[total_index][col] = sum(
            matrix[row][col] for row in range(size)
        ) % mod
    matrix[total_index][total_index] = 1

    vector = [0] * dim
    vector[0] = 1  # The empty sequence has all exponent moments zero.

    def multiply_matrices(left, right):
        result = [[0] * dim for _ in range(dim)]
        for i in range(dim):
            out = result[i]
            left_row = left[i]
            for k, a in enumerate(left_row):
                if a:
                    right_row = right[k]
                    for j, b in enumerate(right_row):
                        if b:
                            out[j] = (out[j] + a * b) % mod
        return result

    def multiply_vector(mat, vec):
        result = [0] * dim
        for i, row in enumerate(mat):
            value = 0
            for j, a in enumerate(row):
                if a and vec[j]:
                    value += a * vec[j]
            result[i] = value % mod
        return result

    exponent = n
    while exponent:
        if exponent & 1:
            vector = multiply_vector(matrix, vector)
        exponent >>= 1
        if exponent:
            matrix = multiply_matrices(matrix, matrix)
    return vector[total_index]

