    seen = {start}
    while q:
        cur, dist = q.popleft()
        for nxt in neighbors(cur):
            if nxt == target:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, dist + 1))
    return 0

